const b = $json.body || {};
const c = b.client || {};
const header = 'Known client: company=' + (c.company||'') + ', contact=' + (c.contactName||'') + ', email=' + (c.contactEmail||'') + ', industry=' + (c.industry||'') + '\n\n';
return [{ json: { transcript: header + (b.transcript||''), source: (b.source||'intake'), date: new Date().toISOString().slice(0,10) } }];
